package practice;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Which actions each role may perform. The authorizer keeps one policy for as long as the
 * service runs and asks it on every request.
 */
public final class AccessPolicy {

    private final Map<String, List<String>> actionsByRole;

    public AccessPolicy(Map<String, List<String>> actionsByRole) {
        this.actionsByRole = frozenCopy(actionsByRole);
    }

    public boolean allows(String role, String action) {
        return actionsFor(role).contains(action);
    }

    /** The actions of one role, in the order they were given; empty for a role it doesn't know. */
    public List<String> actionsFor(String role) {
        return actionsByRole.getOrDefault(role, List.of());
    }

    public Set<String> roles() {
        return actionsByRole.keySet();
    }

    /**
     * The table this policy keeps, built from what the caller passed in.
     */
    static Map<String, List<String>> frozenCopy(Map<String, List<String>> source) {
        Map<String, List<String>> copy = new HashMap<>();
        source.forEach((role, actions) -> copy.put(role, List.copyOf(actions)));
        return Map.copyOf(copy);
    }
}

package practice;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        // Only this handler prints, and it leaves out the JDK's own detail.
        Logger root = Logger.getLogger("");
        for (java.util.logging.Handler before : root.getHandlers()) {
            root.removeHandler(before);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFilter(entry -> !String.valueOf(entry.getLoggerName()).matches("(java|javax|jdk|sun|com\\.sun)\\..*"));
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            Map<String, List<String>> table = new LinkedHashMap<>();
            table.put("support", new ArrayList<>(List.of("view-tickets", "reply-ticket")));
            table.put("admin", new ArrayList<>(List.of("create-user", "reset-password", "view-tickets")));
            AccessPolicy policy = new AccessPolicy(table);
            System.out.println("admin actions: " + policy.actionsFor("admin"));
            System.out.println("support may reply-ticket: " + policy.allows("support", "reply-ticket"));
            System.out.println("support may create-user: " + policy.allows("support", "create-user"));
            System.out.println("guest may view-tickets: " + policy.allows("guest", "view-tickets"));
            table.get("support").add("delete-user");
            try {
                policy.actionsFor("admin").add("drop-database");
            } catch (UnsupportedOperationException refused) {
                System.out.println("adding to a returned list: refused");
            }
            System.out.println("support may delete-user, after the loader changed its list: " + policy.allows("support", "delete-user"));
            System.out.println("admin actions, after all that: " + policy.actionsFor("admin"));
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }
}

